// Labeler trial v2: MiniRBT-H256 span labeler on browser CPU (ONNX Runtime
// Web 1.30.0 direct), marking ITEM/TGT character spans in player actions.
//
// DATA CONTRACT: dev/scored/acceptance cases are NOT kept in this file any
// more. Everything is loaded from artifacts/benchmark/span-labeler-corpus.json
// (generated by train-span-labeler.py), and the report records the file's
// sha256 plus the model file hashes, so Python and browser literally score
// the same bytes. If the manifest is missing or stale the trial fails fast.
//
// PRE-REGISTERED ACCEPTANCE (unchanged): on the SEALED acceptance batch,
// strict span match (start+end+type exact) >= 90% per field AND end-to-end
// <= 4s per call. The sealed batch is evaluated EXACTLY ONCE — only when
// this script is run with --with-acceptance. Without the flag the batch is
// loaded NOWHERE (never sent to the browser) and the gate reports
// "not-evaluated"; dev batches (classic + grouped) are diagnostics only.
// Additionally reported (non-gating): both-fields-correct rate per batch.
//
// Per-token diagnostics (this round): for dev batches every case records
// per-token gold/pred tags + softmax probabilities and a span-level error
// class (taxonomy in the manifest's errorTaxonomy: truncated-b,
// truncated-o, wrong-field, modifier-as-head, ...), mirroring
// train-span-labeler.py's diagnose() exactly.
//
// Timing scope (per classifier-trial v2 review): end-to-end per call —
// raw text -> tokenize -> feed -> run -> argmax -> span decode -> substrings.
// Threads: measured single-thread; >1-thread session create hangs in this
// environment (documented in run-classifier-trial.mjs, headed and headless).
//
// Usage: node scripts/run-labeler-trial.mjs [--with-acceptance]
// Output: artifacts/benchmark/labeler-trial-<ts>-spans.json

import { mkdir, readFile, writeFile } from "node:fs/promises";
import { createHash } from "node:crypto";
import os from "node:os";
import path from "node:path";
import { fileURLToPath } from "node:url";

import { chromium } from "@playwright/test";

const frontendRoot = path.dirname(path.dirname(fileURLToPath(import.meta.url)));
const baseUrl = process.env.BASE_URL ?? "http://localhost:3100";
const TARGET_MS = 4000;
const REPEATS = 10;
const CREATE_TIMEOUT_MS = 30000;

const MODEL_DIR = "/models/minirbt-h256-span";
const MODEL_ROOT = path.join(frontendRoot, "public", "models", "minirbt-h256-span");
const MANIFEST_PATH = path.join(frontendRoot, "..", "artifacts", "benchmark", "span-labeler-corpus.json");
const TAGS = ["O", "B-ITEM", "I-ITEM", "B-TGT", "I-TGT"];

const sha256 = (buffer) => createHash("sha256").update(buffer).digest("hex");

const log = (...parts) => console.log(new Date().toISOString().slice(11, 19), ...parts);

async function main() {
  const evalAcceptance = process.argv.includes("--with-acceptance");

  // ── 唯一数据源：语料 manifest（Python 训练脚本生成）。───────
  const manifestBytes = await readFile(MANIFEST_PATH);
  const manifest = JSON.parse(manifestBytes.toString("utf-8"));
  for (const key of ["devClassic", "devGroups", "scored", "acceptance", "counts", "errorTaxonomy", "acceptanceProtocol"]) {
    if (!manifest[key]) {
      console.error(`FATAL: ${MANIFEST_PATH} is missing "${key}" — regenerate it via train-span-labeler.py --export-corpus`);
      process.exit(2);
    }
  }
  const dataSha = sha256(manifestBytes);
  log(`data: ${path.relative(frontendRoot, MANIFEST_PATH)} sha256=${dataSha.slice(0, 16)}…`);
  log(`sealed acceptance: ${manifest.acceptance.reduce((n, g) => n + g.sentences.length, 0)} sentences -> ${evalAcceptance ? "WILL be evaluated (single-shot per protocol)" : "NOT evaluated (flag --with-acceptance absent)"}`);

  const modelFiles = {};
  for (const rel of ["onnx/model.onnx", "onnx/model_quantized.onnx", "vocab.txt", "config.json"]) {
    try {
      const buf = await readFile(path.join(MODEL_ROOT, rel));
      modelFiles[rel] = { size: buf.length, sha256: sha256(buf) };
    } catch {
      modelFiles[rel] = null;
    }
  }

  const cpu = os.cpus()[0]?.model ?? "unknown";
  log(`host CPU: ${cpu}`);

  const browser = await (async () => {
    try {
      return await chromium.launch({ channel: "msedge", headless: true });
    } catch {
      return chromium.launch({ headless: true });
    }
  })();
  const page = await browser.newPage();
  await page.goto(`${baseUrl}/benchmark`);
  await page.waitForLoadState("domcontentloaded");
  const isolated = await page.evaluate(() => window.crossOriginIsolated === true);
  const userAgent = await page.evaluate(() => navigator.userAgent);
  log(`crossOriginIsolated: ${isolated}`);
  if (!isolated) {
    console.error("FATAL: not cross-origin isolated; wasm multithread unavailable.");
    await browser.close();
    process.exit(2);
  }

  // 评估批：devClassic/devGroups/scored 恒评；封存验收批仅在显式 flag 下
  // 交给浏览器（协议：恰评一次）。
  const batches = [
    { name: "devClassic", rows: manifest.devClassic, tokens: true },
    { name: "devGroups", rows: manifest.devGroups.flatMap((g) => g.sentences.map((s) => ({ ...s, group: g.group }))), tokens: true },
    { name: "scored", rows: manifest.scored, tokens: false },
  ];
  if (evalAcceptance) {
    batches.push({ name: "acceptance", rows: manifest.acceptance.flatMap((g) => g.sentences.map((s) => ({ ...s, group: g.group }))), tokens: false });
  }

  const armConfigs = [
    { name: "q8-t1", threads: 1, file: "onnx/model_quantized.onnx" },
    { name: "fp32-t1", threads: 1, file: "onnx/model.onnx" },
  ];
  const arms = [];
  for (const armConfig of armConfigs) {
    const armPage = await browser.newPage();
    await armPage.goto(`${baseUrl}/benchmark`);
    await armPage.waitForLoadState("domcontentloaded");
    const arm = await armPage.evaluate(
      async ({ modelDir, tags, batches, threads, file, repeats, targetMs, timeoutMs }) => {
        const ort = await import("/ort/ort.bundle.min.mjs");
        ort.env.wasm.wasmPaths = "/ort/";
        ort.env.wasm.numThreads = threads;

        const vocabText = await fetch(`${window.location.origin}${modelDir}/vocab.txt`).then((r) => r.text());
        const vocab = new Map();
        vocabText.split("\n").forEach((line, index) => vocab.set(line.replace(/\r$/, ""), index));

        // 分词并保留每 token 的字符区间（与 Python 的 offset_mapping 对齐：
        // 特殊 token 为 [0,0)；中文逐字；ASCII 段最长 wordpiece，piece 自带
        // 前缀"##"的字符数即其区间宽度）。
        const tokenizeWithOffsets = (text, maxLen = 48) => {
          const ids = [vocab.get("[CLS]")];
          const offsets = [[0, 0]];
          let asciiRun = null; // 审查修正：此前初始化为数组、后面却按对象用，英文首段必坏
          const flushAscii = () => {
            if (!asciiRun) return;
            const { word, start: base } = asciiRun;
            asciiRun = null;
            let start = 0;
            while (start < word.length && ids.length < maxLen - 1) {
              let end = word.length;
              let id = null;
              while (end > start) {
                const piece = start === 0 ? word.slice(start, end) : "##" + word.slice(start, end);
                if (vocab.has(piece)) {
                  id = vocab.get(piece);
                  break;
                }
                end -= 1;
              }
              if (id === null) {
                id = vocab.get("[UNK]");
                end = start + 1;
              }
              ids.push(id);
              offsets.push([base + start, base + end]);
              start = end;
            }
          };
          const chars = [...text];
          for (let index = 0; index < chars.length; index += 1) {
            const raw = chars[index];
            const ch = raw.toLowerCase();
            if (/\s/.test(ch)) {
              flushAscii();
              continue;
            }
            if (/[a-z0-9]/.test(ch)) {
              if (!asciiRun) asciiRun = { word: "", start: index };
              asciiRun.word += ch;
              continue;
            }
            flushAscii();
            if (ids.length >= maxLen - 1) break;
            ids.push(vocab.has(ch) ? vocab.get(ch) : vocab.get("[UNK]"));
            offsets.push([index, index + 1]);
          }
          flushAscii();
          ids.push(vocab.get("[SEP]"));
          offsets.push([0, 0]);
          return { ids: ids.slice(0, maxLen), offsets: offsets.slice(0, maxLen) };
        };

        // 与 train-span-labeler.py 的 tags_to_spans 同逻辑（组尾取组内最后
        // 片段的结束位置，而非下一个 token 的起点——句末特殊标记起点是 0）。
        const decodeSpans = (offsets, tagIds) => {
          const spans = { ITEM: null, TGT: null };
          let current = null;
          const flush = () => {
            if (current !== null && spans[current.type] === null) {
              spans[current.type] = [current.start, current.end];
            }
            current = null;
          };
          tagIds.forEach((tagId, index) => {
            const [tokenStart, tokenEnd] = offsets[index];
            const tag = tokenEnd === 0 || tagId >= tags.length ? "O" : tags[tagId];
            if (tag.startsWith("I-") && current !== null && current.type === tag.slice(2)) {
              current.end = tokenEnd;
              return;
            }
            flush();
            if (tag !== "O") current = { type: tag.slice(2), start: tokenStart, end: tokenEnd };
          });
          flush();
          return { ITEM: spans.ITEM, TGT: spans.TGT };
        };

        // 与 train-span-labeler.py 的 diagnose_field 同口径（taxonomy 见
        // manifest.errorTaxonomy）。
        const diagnoseField = (text, gold, pred, otherGold, tokenRows, field, other) => {
          if (gold === null && pred === null) return "ok";
          if (gold === null) return "false-positive";
          const goldTokens = tokenRows.filter((row) => row.start < gold[1] && gold[0] < row.end);
          if (pred === null) {
            const preds = [...new Set(goldTokens.map((row) => row.pred))];
            if (preds.length === 1 && preds[0] === "O") return "missed-o";
            if (preds.some((p) => p.endsWith(other))) return "wrong-field";
            return "missed-mixed";
          }
          if (pred[0] === gold[0] && pred[1] === gold[1]) return "ok";
          if (pred[0] < gold[1] && gold[0] < pred[1]) {
            if (pred[0] >= gold[0] && pred[1] <= gold[1]) {
              const midB = goldTokens.some((row) => row.gold === `I-${field}` && row.pred === `B-${field}`);
              if (midB) return "truncated-b";
              if (goldTokens.some((row) => row.pred === "O")) return "truncated-o";
            }
            return "partial";
          }
          if (gold[0] <= pred[0] && pred[1] <= gold[1]) return "partial";
          if (otherGold !== null && pred[0] < otherGold[1] && otherGold[0] < pred[1]) return "wrong-field";
          if (pred[1] <= gold[0]) {
            const gap = text.slice(pred[1], gold[0]);
            if (gap.includes("的") || text.slice(pred[0], pred[1]).endsWith("的")) return "modifier-as-head";
            return "displaced";
          }
          return "displaced";
        };

        const config = await fetch(`${window.location.origin}${modelDir}/config.json`).then((r) => r.json());
        const id2tag = config.id2label ?? null;
        const tagIndexLookup = (mapping, index) => {
          const tag = mapping[String(index)];
          return tags.indexOf(tag) >= 0 ? tags.indexOf(tag) : 0;
        };

        const extract = (session, text) => {
          const { ids, offsets } = tokenizeWithOffsets(text);
          const feed = {
            input_ids: new ort.Tensor("int64", BigInt64Array.from(ids.map(BigInt)), [1, ids.length]),
            attention_mask: new ort.Tensor("int64", BigInt64Array.from({ length: ids.length }, () => 1n), [1, ids.length]),
            token_type_ids: new ort.Tensor("int64", BigInt64Array.from({ length: ids.length }, () => 0n), [1, ids.length]),
          };
          return session.run(feed).then((output) => {
            const logits = output.logits.data; // [seq, tags] Float32Array
            const seq = output.logits.dims[1];
            const tagCount = output.logits.dims[2];
            const tagIds = [];
            const probs = [];
            for (let index = 0; index < seq; index += 1) {
              let best = 0;
              let bestValue = -Infinity;
              let sum = 0;
              for (let tagIndex = 0; tagIndex < tagCount; tagIndex += 1) {
                const value = logits[index * tagCount + tagIndex];
                sum += Math.exp(value);
                if (value > bestValue) {
                  bestValue = value;
                  best = tagIndex;
                }
              }
              tagIds.push(id2tag ? tagIndexLookup(id2tag, best) : best);
              const row = [];
              for (let tagIndex = 0; tagIndex < tagCount; tagIndex += 1) {
                row.push(Math.exp(logits[index * tagCount + tagIndex]) / sum);
              }
              probs.push(row);
            }
            const spans = decodeSpans(offsets, tagIds);
            return {
              item: spans.ITEM !== null ? text.slice(spans.ITEM[0], spans.ITEM[1]) : null,
              target: spans.TGT !== null ? text.slice(spans.TGT[0], spans.TGT[1]) : null,
              itemSpan: spans.ITEM,
              targetSpan: spans.TGT,
              offsets,
              tagIds,
              probs,
            };
          });
        };

        const createStarted = performance.now();
        let session;
        try {
          session = await Promise.race([
            ort.InferenceSession.create(`${window.location.origin}${modelDir}/${file}`, {
              executionProviders: ["wasm"],
            }),
            new Promise((_, reject) => setTimeout(() => reject(new Error("CREATE-HANG")), timeoutMs)),
          ]);
        } catch (error) {
          if (error.message === "CREATE-HANG") {
            return { status: "create-hung", threads, file, timeoutMs };
          }
          throw error;
        }
        const loadMs = Math.round(performance.now() - createStarted);

        const runCase = async (batch, entry, withTokens) => {
          const walls = [];
          let result = null;
          for (let run = 0; run < repeats + 1; run += 1) {
            const started = performance.now();
            result = await extract(session, entry.text);
            const wall = performance.now() - started;
            if (run > 0) walls.push(Math.round(wall * 1000) / 1000);
          }
          const sorted = [...walls].sort((a, b) => a - b);
          const median = sorted[Math.floor(sorted.length / 2)];
          const fieldScore = (expected, span) => {
            if (expected === null && span === null) return { strict: true, loose: true };
            if (expected !== null && span !== null) {
              const strict = span[0] === entry.text.indexOf(expected) && span[1] === span[0] + expected.length;
              const loose = span[0] < entry.text.indexOf(expected) + expected.length && entry.text.indexOf(expected) < span[1];
              return { strict, loose };
            }
            return { strict: false, loose: false };
          };
          const itemScore = fieldScore(entry.item, result.itemSpan);
          const targetScore = fieldScore(entry.target, result.targetSpan);

          const row = {
            batch,
            group: entry.group ?? null,
            text: entry.text,
            expectItem: entry.item,
            expectTarget: entry.target,
            predItem: result.item,
            predTarget: result.target,
            itemSpan: result.itemSpan,
            targetSpan: result.targetSpan,
            itemStrict: itemScore.strict,
            itemLoose: itemScore.loose,
            targetStrict: targetScore.strict,
            targetLoose: targetScore.loose,
            wallMs: Math.round(median * 1000) / 1000,
            withinTarget: median <= targetMs,
          };

          // 逐字诊断（与 train-span-labeler.py 的 diagnose 同口径）：金标
          // 按 mid-char 投影到 token；softmax 概率取 p(pred)/p(gold)。
          const goldSpans = {
            ITEM: entry.item !== null ? [entry.text.indexOf(entry.item), entry.text.indexOf(entry.item) + entry.item.length] : null,
            TGT: entry.target !== null ? [entry.text.indexOf(entry.target), entry.text.indexOf(entry.target) + entry.target.length] : null,
          };
          const tokenRows = [];
          for (let index = 1; index < result.offsets.length; index += 1) {
            const [tokenStart, tokenEnd] = result.offsets[index];
            if (tokenEnd === 0) continue; // [SEP]
            const mid = (tokenStart + tokenEnd) >>> 1;
            let goldTag = "O";
            for (const name of ["ITEM", "TGT"]) {
              const span = goldSpans[name];
              if (span !== null && span[0] <= mid && mid < span[1]) {
                goldTag = `${mid === span[0] ? "B" : "I"}-${name}`;
                break;
              }
            }
            tokenRows.push({
              start: tokenStart,
              end: tokenEnd,
              ch: entry.text.slice(tokenStart, tokenEnd),
              gold: goldTag,
              pred: tags[result.tagIds[index]] ?? "O",
              pPred: Math.round(result.probs[index][result.tagIds[index]] * 10000) / 10000,
              pGold: Math.round(result.probs[index][tags.indexOf(goldTag)] * 10000) / 10000,
            });
          }
          row.diagnosis = {
            item: diagnoseField(entry.text, goldSpans.ITEM, result.itemSpan, goldSpans.TGT, tokenRows, "ITEM", "TGT"),
            target: diagnoseField(entry.text, goldSpans.TGT, result.targetSpan, goldSpans.ITEM, tokenRows, "TGT", "ITEM"),
          };
          if (withTokens) row.tokens = tokenRows;
          return row;
        };

        const coldStarted = performance.now();
        await extract(session, batches.find((b) => b.name === "scored").rows[0].text);
        const coldMs = Math.round(performance.now() - coldStarted);

        const cases = [];
        for (const batch of batches) {
          for (const entry of batch.rows) {
            cases.push(await runCase(batch.name, entry, batch.tokens));
          }
        }

        return {
          status: "ok",
          threads,
          file,
          loadMs,
          coldMs,
          cases,
        };
      },
      {
        modelDir: MODEL_DIR,
        tags: TAGS,
        batches,
        threads: armConfig.threads,
        file: armConfig.file,
        repeats: REPEATS,
        targetMs: TARGET_MS,
        timeoutMs: CREATE_TIMEOUT_MS,
      },
    );
    await armPage.close();
    arms.push({ name: armConfig.name, ...arm });
    log(`${armConfig.name}: ${arm.status === "ok" ? `load=${arm.loadMs}ms cold=${arm.coldMs}ms` : arm.status}`);
  }
  await browser.close();

  const scoredArms = arms.filter((arm) => arm.status === "ok");
  const batchNames = batches.map((b) => b.name);
  const summarizeBatch = (arm, batch, field) => {
    const rows = arm.cases.filter((row) => row.batch === batch);
    return `${rows.filter((row) => row[`${field}Strict`]).length}/${rows.length}`;
  };
  const bothRate = (arm, batch) => {
    const rows = arm.cases.filter((row) => row.batch === batch);
    return `${rows.filter((row) => row.itemStrict && row.targetStrict).length}/${rows.length}`;
  };
  for (const arm of scoredArms) {
    const parts = batchNames.map((batch) => `${batch} ITEM ${summarizeBatch(arm, batch, "item")} TGT ${summarizeBatch(arm, batch, "target")} both ${bothRate(arm, batch)}`);
    const medianWall = arm.cases.map((row) => row.wallMs).sort((a, b) => a - b)[Math.floor(arm.cases.length / 2)];
    log(`${arm.name}: ${parts.join(" | ")} | medianWall=${medianWall}ms`);
  }
  const primary = scoredArms[0]?.cases ?? [];

  // 错误类别聚合（dev 批；分类口径见 manifest.errorTaxonomy）。
  const devDiagnostics = {};
  for (const batch of ["devClassic", "devGroups"]) {
    const counts = {};
    for (const field of ["item", "target"]) {
      counts[field] = {};
      for (const row of primary.filter((r) => r.batch === batch)) {
        const cls = row.diagnosis?.[field] ?? "n/a";
        counts[field][cls] = (counts[field][cls] ?? 0) + 1;
      }
    }
    devDiagnostics[batch] = counts;
    log(`${batch} errors: item ${JSON.stringify(counts.item)} target ${JSON.stringify(counts.target)}`);
  }

  // 预注册验收判定：封存批每字段 strict >= 90% 且端到端 <= 4s；dev 批只
  // 作诊断。未传 --with-acceptance 时判定记 not-evaluated（批未加载）。
  let gate;
  if (evalAcceptance) {
    const acceptanceRows = primary.filter((row) => row.batch === "acceptance");
    gate = {
      evaluated: true,
      itemStrictRate: `${acceptanceRows.filter((row) => row.itemStrict).length}/${acceptanceRows.length}`,
      targetStrictRate: `${acceptanceRows.filter((row) => row.targetStrict).length}/${acceptanceRows.length}`,
      itemPass: acceptanceRows.filter((row) => row.itemStrict).length / acceptanceRows.length >= 0.9,
      targetPass: acceptanceRows.filter((row) => row.targetStrict).length / acceptanceRows.length >= 0.9,
      bothFieldsCorrectRate: `${acceptanceRows.filter((row) => row.itemStrict && row.targetStrict).length}/${acceptanceRows.length}`,
      latencyAllWithinTarget: primary.every((row) => row.withinTarget),
      verdict: null,
    };
    gate.verdict = gate.itemPass && gate.targetPass && gate.latencyAllWithinTarget ? "accepted" : "rejected";
    log(`pre-registered gate: ITEM ${gate.itemStrictRate} TGT ${gate.targetStrictRate} both ${gate.bothFieldsCorrectRate} -> ${gate.verdict}`);
  } else {
    gate = {
      evaluated: false,
      note: "sealed acceptance batch was NOT loaded or evaluated (protocol: single-shot via --with-acceptance after dev justifies it); gates: per-field strict >= 90% AND e2e <= 4s on that batch",
      perBatchBothFieldsCorrect: Object.fromEntries(batchNames.map((batch) => [batch, scoredArms[0] ? bothRate(scoredArms[0], batch) : "0/0"])),
      verdict: "not-evaluated",
    };
    log(`gate: not-evaluated (sealed); dev/scored both-fields: ${JSON.stringify(gate.perBatchBothFieldsCorrect)}`);
  }

  const outDir = path.join(frontendRoot, "..", "artifacts", "benchmark");
  await mkdir(outDir, { recursive: true });
  const outPath = path.join(outDir, `labeler-trial-${Date.now()}-spans.json`);
  await writeFile(
    outPath,
    JSON.stringify(
      {
        hostCpu: cpu,
        task: "span-labeling",
        data: {
          file: path.relative(frontendRoot, MANIFEST_PATH),
          sha256: dataSha,
          counts: manifest.counts,
          acceptanceProtocol: manifest.acceptanceProtocol,
          attributionNote: manifest.attributionNote,
        },
        model: {
          dir: MODEL_DIR,
          base: "hfl/minirbt-h256 (~10.4M params, token-classification head)",
          files: modelFiles,
        },
        runtime: {
          userAgent,
          crossOriginIsolated: isolated,
          timingScope: "end-to-end per call: text -> tokenize -> feed -> run -> argmax -> span decode",
          threadNote: "single-thread only; >1-thread wasm session create hangs in this environment",
        },
        targetMs: TARGET_MS,
        repeatsPerCase: REPEATS,
        errorTaxonomy: manifest.errorTaxonomy,
        acceptance: {
          evaluated: evalAcceptance,
          sealedSentences: manifest.acceptance.reduce((n, g) => n + g.sentences.length, 0),
          gate,
        },
        devDiagnostics,
        arms: scoredArms,
        exportedAt: new Date().toISOString(),
      },
      null,
      2,
    ),
  );
  log(`saved: ${outPath}`);
}

main().catch((error) => {
  console.error(error);
  process.exit(1);
});
